-- Guided paths and teaching series. GENERATED by `node scripts/paths.mjs build` from
-- content/paths/*.json: edit those files, never this one (CI fails when they differ).
-- Idempotent: re-running updates the text and days in place and removes days beyond
-- each path's last day. It never changes status, so a new path arrives as a draft and a
-- published one stays published, and it never deletes a path.
-- Requires the paths, teaching series and teaching start migrations and the sermon
-- catalogue (every youtube_id must exist in public.sermons). Guide: docs/development/paths.md.

begin;

insert into public.paths (id, kind, name, italic, promise, why, needs, minutes_per_day, status, sort) values
  ('hearing-the-voice-of-god', 'path', 'Hearing the voice of God', 'voice of God',
   'Five days to recognise how God speaks to you, and to answer.',
   'For believers who long to hear God but are unsure what his voice sounds like. The path explains the senses of the recreated spirit, how knowings and the inner voice work, how to tell his voice from your own, how Scripture becomes his voice, and why obedience keeps your hearing clear.',
   array['hear-god']::text[], 14, 'draft', 1),
  ('building-a-life-of-prayer', 'path', 'Building a life of prayer', 'life of prayer',
   'Six days from occasional prayer to a daily place with God.',
   'For believers who want to pray but find it hard to start or to stay consistent. The path begins with why we were made to pray, then moves through giving yourself to prayer, finding your place, guarding your time and praying in the Spirit, and ends with the persistence that keeps knocking.',
   array['prayer']::text[], 16, 'draft', 2),
  ('discovering-your-purpose-and-calling', 'path', 'Discovering your purpose and calling', 'purpose and calling',
   'Six days on why you were made and how to walk in it.',
   'For anyone asking what their life is for. The path defines a call from God, roots purpose in Christ the Maker, helps you take inventory of the grace on your life, shows what a call carries, and asks for faithfulness in small things and steadiness in your assignment.',
   array['purpose', 'calling']::text[], 14, 'draft', 3),
  ('learning-to-wait-on-god', 'path', 'Learning to wait on God', 'wait on God',
   'Six days on staying faithful when God''s promise seems slow.',
   'For anyone in a season where prayers seem unanswered and promises delayed. The path shows why God makes us wait, how he renews strength while we wait, the danger of helping God in the flesh, and how to keep believing until the word comes to pass.',
   array['waiting', 'delay']::text[], 14, 'draft', 4),
  ('overcoming-fear-and-anxiety', 'path', 'Overcoming fear and anxiety', 'fear and anxiety',
   'Five days to trade anxious thoughts for the peace of God.',
   'For anyone whose mind races with worry about money, health or the future. The path names how anxiety works, roots you in the Father who already knows your needs, and builds habits of prayer and inner quietness that let God''s peace guard your heart.',
   array['fear', 'anxiety']::text[], 15, 'draft', 5),
  ('walking-in-grace-and-holiness', 'path', 'Walking in grace and holiness', 'grace and holiness',
   'Five days on the grace that teaches us to live holy.',
   'For believers who have heard that grace covers everything and want to see how grace and holiness belong together. The path corrects the abuse of grace, describes holiness as oneness with God, and builds the daily habits of consecration, godly fear and a growing knowledge of God.',
   array['holiness', 'grace']::text[], 16, 'draft', 6),
  ('fasting-with-purpose', 'path', 'Fasting with purpose', 'with purpose',
   'Five days on why to fast, how to fast and how to fast wisely.',
   'For believers who want to fast but are unsure of the reason or the right way. The path follows Jesus into the wilderness, explains what fasting does to the flesh and the spirit, gives practical guidance with limits, and ends with fasting as part of a temperate, disciplined life.',
   array['fasting']::text[], 14, 'draft', 7),
  ('breaking-free-from-habitual-sin', 'path', 'Breaking free from habitual sin', 'habitual',
   'Six days from the grip of a repeated sin to the freedom grace gives.',
   'For the believer who keeps returning to the same sin and is tired of starting over. The path begins with how temptation actually works, grounds you in the truth that you are dead to sin, then builds practical disciplines for the mind and the appetites. It ends at the throne of grace, for the days you fall.',
   array['same-sin']::text[], 16, 'draft', 8),
  ('building-on-the-right-foundation', 'series', 'Building on the right foundation', 'the right foundation',
   'From what salvation is to a steady, growing walk with God: twelve foundations every believer can build on.',
   'For new believers and anyone who never had a solid grounding. It starts with what salvation is and how it begins (turning from the old life, believing in Jesus, the new birth), then settles who you now are (a new creation, made righteous, empowered by grace, marked by communion and baptism), then builds the daily habits (the Word, prayer, meeting with the church) and ends with growing up: the lifelong salvation of the soul.',
   '{}'::text[], 22, 'draft', 101),
  ('knowing-the-holy-spirit', 'series', 'Knowing the Holy Spirit', 'the Holy Spirit',
   'Meet the Holy Spirit as a Person, then learn step by step to be filled, taught and led by him every day.',
   'For believers who know about the Holy Spirit but want to walk with him. It starts with who he is and why Jesus sent him, shows how he lives in your spirit and fills you with power, then builds daily practice: praying in tongues, fellowship with him, his inner teaching and leading. Later teachings cover his gifts and anointing for serving others and how to honour rather than grieve him, and the series ends with walking in the Spirit day by day.',
   '{}'::text[], 19, 'draft', 102),
  ('the-way-of-the-cross', 'series', 'The way of the cross', 'the cross',
   'See what Jesus did on the cross, what it makes you, and how to live the crucified life.',
   'For believers who want to understand what the cross accomplished and what it asks of them. It starts with what Jesus did there and the exchange he made in our place, then shows that you died and rose with him, and ends with God''s daily dealings with self and the cost and reward of following him.',
   '{}'::text[], 20, 'draft', 103),
  ('living-by-faith', 'series', 'Living by faith', 'by faith',
   'Six teachings that take faith from what it is to how it holds, real and steady, through every season.',
   'For believers who want faith that is real and steady, not hype. It starts with what faith is and where it comes from (God''s spoken word), shows the spirit of faith that sees and acts, then walks through the trial of faith, the patience it needs and the long road, so that faith holds to the end.',
   '{}'::text[], 22, 'draft', 104),
  ('seeking-the-face-of-god', 'series', 'Seeking the face of God', 'the face',
   'One teaching: learn what it means to seek God''s face, how to do it, and how to know you have met him.',
   'For any believer, including someone new to faith. In one complete teaching he shows why we seek God (we were made to need him), what seeking his face means in real decisions, how to keep the mind engaged in prayer, and the sign that you have met him: anxiety lifts and you are at rest.',
   '{}'::text[], 27, 'draft', 105)
on conflict (id) do update set
  kind = excluded.kind,
  name = excluded.name,
  italic = excluded.italic,
  promise = excluded.promise,
  why = excluded.why,
  needs = excluded.needs,
  minutes_per_day = excluded.minutes_per_day,
  sort = excluded.sort;

insert into public.path_days (path_id, day, youtube_id, focus_start, focus_end, theme, key_at, key_title, key_quote, teaching_start) values
  ('hearing-the-voice-of-god', 1, '32cOFekz4ds', 3803.4, 4545, 'Your spirit was made to hear God', 4125.2, 'The voice within',
   'That voice is not without. That voice is within.', null),
  ('hearing-the-voice-of-god', 2, 'G3UvVP7US-4', 2829, 3731.2, 'Knowings and the inner voice', 3065.1, 'Small impressions',
   'A little impression is a testimony to a mighty thing.', null),
  ('hearing-the-voice-of-god', 3, 'O1u7szjsr9s', 2726.8, 3689.2, 'Telling his voice from your own', 2883.4, 'His voice or mine',
   'You do not live by his explanations; you live by his instructions.', null),
  ('hearing-the-voice-of-god', 4, '-VxddgaYe9o', 1765.3, 2613.7, 'Let Scripture slow you down to hear', 1787.1, 'Slow down with Scripture',
   'Don''t be in a hurry with Scripture, because you just read it and you don''t know that the scriptures are gateways to spirit dimensions.', null),
  ('hearing-the-voice-of-god', 5, 'AYsESvakKek', 315.2, 1159.1, 'Obedience keeps your hearing clear', 513.7, 'Obey what you hear',
   'The last time you heard God clearly, it was the last time you obeyed him.', null),
  ('building-a-life-of-prayer', 1, 'Kqw36QLZr6E', 1614.8, 2517.9, 'We were made to pray', 2388.4, 'Made to pray',
   'Men ought always to pray, not to faint. You will never enter into that economy until you acknowledge the fact that you are insufficient.', null),
  ('building-a-life-of-prayer', 2, 'wem3w4ZPLyc', 1311.4, 2414.9, 'Give your whole self to prayer', 1322.9, 'Prayer is who we are',
   'Prayer is who we are and not what we do.', null),
  ('building-a-life-of-prayer', 3, 'TWiVZeKhO2w', 1158.8, 2199, 'Find your point of prayer', 1613, 'The point of prayer',
   'It is when you arrive the point of prayer that you can begin to offer your prayer point.', null),
  ('building-a-life-of-prayer', 4, 'YGnx3g5xOzQ', 571.2, 1599.8, 'Shut the door and keep the time', 991.6, 'Shut the door',
   'Shut the door is a serious business; it''s not something that you can do double-minded.', null),
  ('building-a-life-of-prayer', 5, 'A3YdLXMlRxg', 472, 1088, 'Build yourself up in the Spirit', 819.3, 'Build yourself up',
   'There are dimensions of believing that become possible when you gain heights in the Spirit.', null),
  ('building-a-life-of-prayer', 6, '5e7Y83Z7BIA', 0, 1113.6, 'Keep knocking and do not faint', 637.3, 'Pray or faint',
   'The opposite of prayerful is not prayerless.', null),
  ('discovering-your-purpose-and-calling', 1, 'itIp_xL8EOk', 1280.8, 2205.2, 'What a call from God is', 2066.3, 'Your meaning is your assignment',
   'It''s not your ability that is your meaning; it''s your assignment that is your meaning.', null),
  ('discovering-your-purpose-and-calling', 2, 'RG2nnvXKKHY', 679.5, 1385.5, 'Purpose is found in the Maker', 854.3, 'Ask the Manufacturer',
   'It is not the product that tells the manufacturer what it was manufactured for.', null),
  ('discovering-your-purpose-and-calling', 3, 'DNkFzBGAHXk', 972.7, 2010.2, 'Take inventory of your grace', 1708, 'Sharpen your grace',
   'When you locate the fact that there is grace in a certain area, you need to labor to sharpen it.', null),
  ('discovering-your-purpose-and-calling', 4, 'VdkD5g4qOFc', 1517.6, 2217.5, 'A call has an objective and place', 1752.3, 'What a call carries',
   'God will not do anything on the earth without a calling.', null),
  ('discovering-your-purpose-and-calling', 5, 'wAYwEhxGYVY', 3071, 3922.5, 'Be faithful in the little things', 3336.9, 'Faithful in little',
   'If you are too big to do little things, you''ll be too little to do big things.', null),
  ('discovering-your-purpose-and-calling', 6, 'aY3Nj2rgk0o', 833.2, 1619.6, 'Your assignment does not change', 1410.7, 'Your assignment stays',
   'You will pass through many seasons in the implementation of that assignment, but the assignment itself does not change.', null),
  ('learning-to-wait-on-god', 1, '-4r-s-jMFbo', 2891.6, 3591.9, 'God is a King, not a servant', 3408.7, 'Waiting on a King',
   'The way up is waiting at the foot of the King until he stretches forth his scepter in your direction.', null),
  ('learning-to-wait-on-god', 2, '0O_H4IyR3lo', 462.3, 1257.2, 'He makes everything beautiful in its time', 784.3, 'Beautiful in its time',
   'God doesn''t live in time, but he will use time to test your soul.', null),
  ('learning-to-wait-on-god', 3, 'MiE70TINsJo', 2920.4, 3694.8, 'Strength renewed for the faint', 3004.5, 'Power for the faint',
   'The specialty of God is that he gives power to the faint.', null),
  ('learning-to-wait-on-god', 4, 'EdDHjGT6zrM', 3473.1, 4430.9, 'Do not help God in the flesh', 3487.1, 'Milk or wine',
   'Wine gets better with time; milk gets bad with time. So the question is, are you milk or are you wine?', null),
  ('learning-to-wait-on-god', 5, '6vzoGqCUSDc', 6380, 7170.1, 'Keep the condition while you wait', 6878, 'Keep the condition',
   'The proof that you believe in a conditional promise is that you are busy fulfilling the condition.', null),
  ('learning-to-wait-on-god', 6, 'TDVokmH0WAw', 3679.8, 4661.7, 'Believe against hope until it comes', 4529.9, 'Believe against hope',
   'No one was there when God spoke to you; you are the only one to bear the burden of your faith.', null),
  ('overcoming-fear-and-anxiety', 1, 'vwKimnaQoco', 3236.6, 4119.1, 'How anxiety tries to win without a fight', 3844.5, 'Anxiety into prayer',
   'Anything that is supposed to make you anxious is the same thing that should draw you to prayer.', null),
  ('overcoming-fear-and-anxiety', 2, 'ezPm1KC_qiE', 1058, 2212.1, 'Your heavenly Father already knows', 2136.5, 'Your Father knows',
   'If you want to deal with a God that knows, the only thing that can impress him is your faith.', null),
  ('overcoming-fear-and-anxiety', 3, 'gP9MubHuVL4', 2655.2, 3264.7, 'Jesus speaks peace to fear and doubt', 2813.2, 'Win in your soul',
   'If you win in your soul you will win on the ground; if you lose in your soul you will lose on the ground.', null),
  ('overcoming-fear-and-anxiety', 4, 'K7n_7hi3xuk', 1879, 2815.7, 'Find inner quietness before you react', 2592.7, 'Quietness within',
   'Do you have quietness within you? Because if you have quietness you will not feel any need to respond.', null),
  ('overcoming-fear-and-anxiety', 5, 'Fal0ICd-XHw', 1189.2, 1875.1, 'Peace that holds until God answers', 1529, 'A place of rest',
   'If you stay in that place of rest, not considering what is in the external, you will begin to see the sovereign hand of God.', null),
  ('walking-in-grace-and-holiness', 1, 'KPcnaSrUpDI', 367.6, 1558.8, 'Grace is not a license for sin', 841.2, 'What grace is not',
   'The antidote for sin cannot become the reason for sin.', null),
  ('walking-in-grace-and-holiness', 2, 'Ey1CtHPRrzY', 1352.6, 2072.6, 'Holiness is oneness with God', 1804, 'One with God',
   'You may not be committing adultery or fornication, but you are not holy because you are not one with God.', null),
  ('walking-in-grace-and-holiness', 3, 'kSMvE2AWlTY', 3562, 4612.6, 'Yield yourself to God every morning', 3668.9, 'Holiness from love',
   'Holy living is not motivated by the fear of hell. Holy living is a function of the fact that you actually stumbled on the love of God.', null),
  ('walking-in-grace-and-holiness', 4, 'GKjIC36hWs0', 3710.2, 4361.7, 'The fear of the Lord keeps you', 3930.5, 'The fear of the Lord',
   'It is only the wisdom of God that can keep you from trespassing into the forbidden zone.', null),
  ('walking-in-grace-and-holiness', 5, '0QjtSGDxR8s', 218, 1298.7, 'Grow from grace to grace', 821.8, 'Grace multiplied',
   'You need a multiplication of grace consistently in your life, and the agency through which this grace is multiplied is through the knowledge of God and the knowledge of our Lord Jesus Christ.', null),
  ('fasting-with-purpose', 1, 'K7n_7hi3xuk', 650.3, 1448.3, 'Why Jesus fasted before the test', 1132.8, 'Fasting, then prayer',
   'When Jesus said fasting and prayer, he meant the environment should not influence you, but you must influence environment.', null),
  ('fasting-with-purpose', 2, 'Yao8V16wrzE', 0, 727.9, 'Build capacity before the battle', 418.2, 'Build capacity',
   'Don''t leave your life to chance. Don''t leave your destiny to chance. Build capacity.', null),
  ('fasting-with-purpose', 3, 'AwoOykuNJGM', 2409.2, 3475.5, 'Fast wisely and within safe limits', 2823.5, 'It changes you',
   'Fasting doesn''t change God; fasting actually changes you.', null),
  ('fasting-with-purpose', 4, 'K1Q19hHq8Do', 7050.2, 7763.3, 'Set your face like Daniel', 7593.8, 'Set your face',
   'If you set your face, it means you have decided to ignore what is behind you.', null),
  ('fasting-with-purpose', 5, '9a6NynM_D2o', 2028.4, 2793.7, 'Be temperate in all things', 2609.1, 'Temperate in all things',
   'The requirement for expertise in the things of the Spirit is that you must master every appetite.', null),
  ('breaking-free-from-habitual-sin', 1, 'G4Waap067c0', 211.3, 1240, 'How temptation finds its way in', 498.9, 'Temptation is personal',
   'Temptation is idiosyncratic; temptation is particular to you.', null),
  ('breaking-free-from-habitual-sin', 2, 'OHhEiiMKXjg', 639, 1606.9, 'You are dead to sin', 1047.9, 'Dead to sin',
   'In the new covenant, this is the accurate position. You must account that you are dead to sin.', null),
  ('breaking-free-from-habitual-sin', 3, 'fxORkBiWxXs', 4291, 5292.1, 'Stop sin while it is a thought', 4880.5, 'Sin starts as a thought',
   'So according to scriptures, bad actions don''t start from actions. Bad actions are incubated through the outlet of the mind until they find expression in the womb of the heart.', null),
  ('breaking-free-from-habitual-sin', 4, 'XHyqYaLSwPk', 1457.6, 2383.9, 'Find the flesh''s booster stations', 1708.1, 'The root is self',
   'The foundation of all sin is self.', null),
  ('breaking-free-from-habitual-sin', 5, 'QaBMqju7NQQ', 598.6, 1664.8, 'Gain mastery over your appetites', 1515.6, 'Learning to say no',
   'Any man that cannot say no to himself cannot say no to others.', null),
  ('breaking-free-from-habitual-sin', 6, 'w-Nb7lByMxg', 3837.6, 4597.6, 'When you fall, come boldly for mercy', 4303.7, 'Mercy, then grace',
   'It''s only those that have obtained mercy that can find grace.', null),
  ('building-on-the-right-foundation', 1, 'UcPjUPgXIFY', 2192.2, 3685.6, 'Saved from sin into a whole new life', 2837.9, 'Saved Into Life',
   'The gospel that the apostles preach provided salvation from the principles, the power and the presence of sin.', null),
  ('building-on-the-right-foundation', 2, 'kJGclK58IcY', 1183.1, 2390.8, 'Turning from rebellion to God''s rule', 1251.9, 'Turn Around',
   'That''s why the first kingdom message is about repentance. We will need to turn around. We need to give up our ways of rebellion.', null),
  ('building-on-the-right-foundation', 3, '4FbUDc0oU5M', 272.7, 1090.5, 'Know for sure that you are his', 651.8, 'The Inward Witness',
   'Your spirit, your human spirit, is calibrated on the same frequency as the Holy Spirit. So the Holy Spirit can communicate with your human spirit. That communication is what we call the inward witness.', null),
  ('building-on-the-right-foundation', 4, 'Rr5boYY_oHY', 3644.9, 5091, 'Born of the Spirit to see God''s kingdom', 5039.1, 'The New Birth',
   'Your being born again gives you the opportunity of perception, then after perception you will need choice to walk under God''s government.', null),
  ('building-on-the-right-foundation', 5, 'Lxu4HOL1cYI', 2563.4, 3389.3, 'Know who you have become in Christ', 3017.2, 'A New Creation',
   'The reason why you are living now as a new creation is that you are living by the Holy Spirit. It means that your life cannot be the way it was.', null),
  ('building-on-the-right-foundation', 6, 'zgTFaaNHSxY', 518.9, 1755.3, 'Declared righteous as a gift, then living it', 1615.2, 'Righteousness, a Gift',
   'This righteousness that was given to us was not a function of something that you achieved by your own power.', null),
  ('building-on-the-right-foundation', 7, 't3runnbXW3M', 375.3, 1439.8, 'Grace: God''s own power to live above sin', 567, 'Grace to Live',
   'Christian life was designed to run on the fuel called grace.', null),
  ('building-on-the-right-foundation', 8, 'HJCY8Mu9vzg', 3955.3, 5205.2, 'Covenant signs: the cup and the water', 4503.8, 'Cup and Water',
   'Your baptism is a declaration to this world that I''ve passed on from you. I''m no longer part of you.', null),
  ('building-on-the-right-foundation', 9, 'Twf18R60vr0', 1565.5, 3146.9, 'Build on the Word: hear it and do it', 3087.4, 'Built on the Word',
   'The difference between your physical mirror and the mirror of the word of God is that the mirror of God''s word reveals who you are supposed to be.', null),
  ('building-on-the-right-foundation', 10, 'zouRZyM9SMM', 0, 1438.8, 'Meet your Father in the secret place', 748.4, 'Prayer in Secret',
   'If God does not touch your heart, God cannot change your life. He changes your life by touching your heart.', null),
  ('building-on-the-right-foundation', 11, 'MA1Z9iT7wX0', 2327.6, 3538.2, 'Gathering with believers where God meets us', 2967.3, 'Meeting Together',
   'So in our fellowship meetings, the people we interact with, the personalities we interact with are not just the physical personalities that are present in church.', null),
  ('building-on-the-right-foundation', 12, 'RmwJQKsQQMg', 0.2, 756.2, 'Saved, being saved, and yet to be saved', 284.4, 'Growing Up in God',
   'It is true when we say we are saved. It is also still true when we say we are being saved.', null),
  ('knowing-the-holy-spirit', 1, 'U8__koxVO7E', 659.2, 2109.3, 'A Person you can know, not a force', 1577, 'A Real Person',
   'That was when I knew that the Holy Ghost was a person, not because I saw it in scripture; I experienced him.', null),
  ('knowing-the-holy-spirit', 2, 'JOTtobPTLOQ', 1461.7, 2472.9, 'From with you to in you', 2334.8, 'Another Comforter',
   'The first blessing that the Holy Spirit makes available when he comes into your ecosystem is that he gives you the blessing of access.', null),
  ('knowing-the-holy-spirit', 3, 'dWukrTfLoh4', 1632.5, 2788.8, 'Joined to the Lord as one spirit', 1792.2, 'The Spirit in You',
   'When you gave your life to Christ, what God did is that he established the economy called one Spirit: your spirit and the Holy Spirit mingled together to form an economy.', null),
  ('knowing-the-holy-spirit', 4, 'L1S2ebzLRTc', 2579.8, 3579.3, 'Ask, receive and speak', 3435.1, 'Filled with Power',
   'That means if you ask him for the Holy Ghost, he will never deny you.', null),
  ('knowing-the-holy-spirit', 5, 'Tl0qEn10FjA', 5277.5, 6697.5, 'Tongues that build you up', 6503.7, 'Praying in Tongues',
   'So speaking in tongues is an avenue to access spiritual rest and spiritual refreshing.', null),
  ('knowing-the-holy-spirit', 6, 'scNJvOyzHZU', 935.1, 2100.2, 'A friendship you build on purpose', 1504.6, 'Communion with Him',
   'God wants you to have a secret life with him.', null),
  ('knowing-the-holy-spirit', 7, 'P5nM7Q6ytBw', 1113.1, 2225.6, 'The anointing within that teaches you', 1637.2, 'Your Inner Teacher',
   'The anointing within is for your maturity; the anointing upon is for ministry.', null),
  ('knowing-the-holy-spirit', 8, 'FFxKz7PKqMw', 3572.9, 4724, 'Telling his leading from your own noise', 4289.7, 'Led from Within',
   'The thoughts that come from your human Spirit, they are in line with the word of God; the thoughts that come from your soul, they are contradictory with the word of God.', null),
  ('knowing-the-holy-spirit', 9, 'sqxHVEU1LU8', 884.2, 2162.3, 'Different gifts, one Spirit', 1347.2, 'Gifts of the Spirit',
   'God can manage you as an individual because he has the administration to do that and that''s why he is not afraid of diversity.', null),
  ('knowing-the-holy-spirit', 10, '2z12UoP47sI', 2155.1, 3288.2, 'Anointed to do good', 2988.6, 'The Anointing',
   'The bottom line is this: you are therefore empowered to do good.', null),
  ('knowing-the-holy-spirit', 11, 'YZFkiPvUELo', 2159.3, 3288.2, 'Honour his lordship, guard his peace', 2668, 'Do Not Grieve Him',
   'The snail is very sensitive. I need you to understand that the Holy Spirit is more sensitive than that snail.', null),
  ('knowing-the-holy-spirit', 12, '02FxbkyFBds', 199.9, 1220.3, 'Learning to walk, step by step', 536.4, 'Walking in the Spirit',
   'Just walk with God and everything that you need for life and for godliness will begin to navigate in your direction.', null),
  ('the-way-of-the-cross', 1, '8Yxk1dA8w-g', 3435.8, 4708.8, 'The cross brought God''s rule to earth', 3895.8, 'Why the cross',
   'The meaning of the cross is the payment that was needed to bring the throne of God and make it efficacious upon the face of the earth.', null),
  ('the-way-of-the-cross', 2, '7aablIT_eDU', 341.6, 1501.8, 'He took our place, we take his', 1145.6, 'The great exchange',
   'It''s not change, but it''s exchange. Exchange. That''s the testimony of the Christian life.', null),
  ('the-way-of-the-cross', 3, 'U6PyFks9W-M', 1011.2, 2104.3, 'You died with Christ to the old', 1362, 'Crucified with Christ',
   'The cross has only one statement to make. The cross says death to the entire old creation.', null),
  ('the-way-of-the-cross', 4, 'AWKMSeH9PZ8', 4770.2, 6098, 'Dead to sin, alive to God', 5834.4, 'Raised with him',
   'My lot and portion experientially on the account of his resurrection is that I am sentenced to a life that is alive to God.', null),
